<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class StaticGen{public static function outDir(){return __DIR__.'/../uisc';}public static function buildAll(){$a=self::outDir();if(!is_dir($a)){mkdir($a,0755,true);}$b=CacheStore::allIds();$c=0;foreach($b as $d){$e=CacheStore::getRowById((int)$d);if(!$e){continue;}file_put_contents($a.'/'.(int)$d.'.html',Views::renderItemPage($e));$c++;}return $c;}public static function buildOne($a){$b=self::outDir();if(!is_dir($b)){mkdir($b,0755,true);}$c=CacheStore::getRowById($a);if(!$c){return false;}file_put_contents($b.'/'.$a.'.html',Views::renderItemPage($c));return true;}}